import java.util.*;

class Solution {
  public long minDamage(int power, int[] damage, int[] health) {
    Integer[] order = new Integer[damage.length];
    for (int i = 0; i < order.length; i++) order[i] = i;
    Arrays.sort(
        order,
        (a, b) -> {
          long left = (long) damage[a] * ((health[b] + power - 1L) / power);
          long right = (long) damage[b] * ((health[a] + power - 1L) / power);
          return Long.compare(right, left);
        });
    long answer = 0, elapsed = 0;
    for (int i : order) {
      long hits = (health[i] + power - 1L) / power;
      elapsed += hits;
      answer += elapsed * damage[i];
    }
    return answer;
  }
}
